UPDATE promotions SET code = #{code}, name = #{name}, type = #{type}, value = #{value},
    buy_qty = #{buyQty}, get_qty = #{getQty}, min_qty = #{minQty}, product_id = #{productId},
    category_id = #{categoryId}, store_id = #{storeId}, coupon_code = #{couponCode},
    starts_at = #{startsAt}, ends_at = #{endsAt}, active = #{active}
WHERE id = #{id}
